Lemma AXS_spci_state_vt' : forall `{HCEIL : HeapCeil} m, AXStatics2 m ->
  rw_cells asegs m AVP_SPCI_STATE (wcells [AVS_SPCI_STATE_0; AVS_SPCI_STATE_8; AVS_SPCI_STATE_16; AVS_SPCI_STATE_24; AVS_SPCI_STATE_32; AVS_SPCI_STATE_40; AVS_SPCI_STATE_48]).
Proof. intros HC m XS. destruct XS as (_ & _ & _ & _ & _ & H0 & _). exact H0. Qed.

Lemma spc_hdr_fold2 : forall `{HCEIL : HeapCeil} m q vp u w i j7,
  rw_cells asegs m q [C8 (Z_to_bv 64 vp); C4 (Z_to_bv 64 u); C4 (Z_to_bv 64 w); C8 (Z_to_bv 64 0); CB 1 [b8 i]; CB 7 j7] ->
  rw_cells asegs m q (SpcHdrCells (mkSPC vp u w i) j7).
Proof. intros HC m q vp u w i j7 RC. exact RC. Qed.
Lemma spc_hdr_fold1 : forall `{HCEIL : HeapCeil} m q vp u w i j7,
  rw_cells asegs m q [C8 (Z_to_bv 64 vp); C4 (Z_to_bv 64 u); C4 (Z_to_bv 64 w); C8 (Z_to_bv 64 0); C1 (Z_to_bv 8 i); CB 7 j7] ->
  rw_cells asegs m q (SpcHdrCells (mkSPC vp u w i) j7).
Proof.
  intros HC m q vp u w i j7 RC. pose proof RC as [[WF _] _]. cbn in WF.
  eapply rw_cells_reshape; [exact RC| cbn; repeat split; lia| reflexivity].
Qed.

