Definition scs_segA_post (sp gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (stb w lo : Z) (j7 : list byte) (ra s0 s1 s2 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' dj,
    ms' = MS (mkR (Z_to_bv 64 ASCS_DISP_RET) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2
                  (Z_to_bv 64 (stb + 24)) (Z_to_bv 64 (Z.shiftr (stb + 24) 3 + 2147450880)) (Z_to_bv 64 (stb + 32)) a1 a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 (Z.shiftr stb 3 + 2147450880)) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_STATE_DTOR) fc None m' (seg_rom asegs)
    /\ munch [(lo, bv_unsigned sp); (stb + 8, stb + 12)]%Z m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp + -64)
    /\ rw_cells asegs m' (bv_unsigned sp + -64) [CB 8 dj; C8 (Z_to_bv 64 2147450880); C8 (Z_to_bv 64 stb); C8 (Z_to_bv 64 ASCS_REL_RET)]
    /\ rw_cells asegs m' (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells asegs m' stb (SpcHdrCells (mkSPC AVP_SPCI_STATE 0 w 1) j7)
    /\ ACONST m'.
