  ro_cells asegs m PC [C8 (wz stb)] -> aplace PC 8 -> (PC + 8 <= lo \/ bv_unsigned sp <= PC) -> PC mod 8 = 0 -> accessible m PC 8 ->
  rw_cells asegs m stb (SpcHdrCells (mkSPC AVP_SPCI_STATE 1 w 1) j7) -> 0 <= w < 2^31 ->
  aapp stb SZ_SPCI_STATE -> stb mod 16 = 0 -> addressable m stb SZ_SPCI_STATE -> (PC + 8 <= stb \/ stb + SZ_SPCI_STATE <= PC) ->
